const STORAGE='ist-lob-studio-v1';
const p=(id,name,time,mp,category='DÁN & ÉP',auto=false)=>({id,name,time,mp,category,auto,x:0,y:0});
const seed={models:{
  s948:{name:'S948',version:'Ver 0.3',processes:[
    p('s1','LASER WELDING',14.94,1,'HÀN LASER'),p('s2','C-CLIP',12.41,0,'C-CLIP',true),p('s3','ATTACH SHEET GASKET (21, 22, 23 P)',15.96,1,'METAL SHEET'),p('s4','ATTACH SHEET GASKET (19, 20, 24, 25 P)',14.96,1,'METAL SHEET'),p('s5','TAPE SPONGE SENSOR FA, TAPE C-CLIP FIX',15.13,1),p('s6','ATTACH METAL SHEET (7, 8, 11 P)',13.92,1,'METAL SHEET'),p('s7','ATTACH METAL SHEET (3, 4, 5, 12, 14 P)',15.38,1,'METAL SHEET'),p('s8','ATTACH METAL SHEET (1, 2, 9, 10, 13 P)',14.83,1,'METAL SHEET'),p('s9','ATTACH METAL SHEET (16, 18 P)',12.93,1,'METAL SHEET'),p('s10','ATTACH METAL SHEET (15, 17 P)',13.04,1,'METAL SHEET'),p('s11','TAPE VC TOP, SPONGE BIT, SPONGE FOD / PRESS',16.16,1),p('s12','MIC HOLD DINO CHECK',12.92,1,'TEST/KIỂM TRA'),p('s13','PROTECT VINYL REAR TOP/BTM',15.42,1,'DÁN VINYL BẢO VỆ'),p('s14','CLEANING',15.88,0,'LÀM SẠCH',true),p('s15','IQC',13.70,1,'KIỂM TRA ĐẦU VÀO'),p('s16','VISION LASER CHECK',15.29,1,'TEST/KIỂM TRA'),p('s17','TAPE VC BTM, SPONGE DDI',14.58,1),p('s18','VAPOR CHAMBER ATTACH',14.72,1,'GẮN TAY'),p('s19','TAPE ABSORBER FOD MMP / PRESS',15.73,1),p('s20','TAPE FRONT MID ATTACH / PRESS',12.90,1),p('s21','SPONGE BIT UPPER + TAPE FRONT GR',14.95,1),p('s22','SPONGE TELE CAM CONN ATTACH / PRESS',15.15,1),p('s23','RUBBER UW CAM + WIDE CAM / PRESS',14.73,1),p('s24','SIDE KEY FPCB_BRK ASSY',11.09,1,'GẮN MẠCH'),p('s25','SIDE KEY ATTACH',14.65,1,'GẮN TAY'),p('s26','LOCKER S PEN, WATER SOAK / PRESS',14.48,1),p('s27','GẮN PHÍM + ROLLING',13.78,1,'ROLLING'),p('s28','EJECTOR PIN + RUBBER HOLDER',12.28,1,'GẮN TAY'),p('s29','S PEN COVER + MIC 2 / PRESS',15.50,1),p('s30','SPONGE VT CAM + MIC 1',14.32,1),p('s31','AIR VENT ASSY / PRESS',14.72,1,'AIRVENT'),p('s32','SPONGE UW CAM CONN + WIDE CAM',15.15,1),p('s33','AGING',10.25,1,'AGING'),p('s34','WPT TEST',15.55,1,'TEST TÍNH NĂNG'),p('s35','S-PEN COVER CHECK',10.50,1,'TEST/KIỂM TRA'),p('s36','WLT TEST',15.59,0,'TEST TÍNH NĂNG',true),p('s37','VSWR TEST + CHECK VISION',16.06,0,'TEST TÍNH NĂNG',true),p('s38','OQC',15.85,1,'KIỂM TRA ĐẦU RA')
  ]},
  s948b3:{name:'S948 Block 3',version:'Ver 0.3',processes:[
    p('b1','IQC',14.01,1,'KIỂM TRA ĐẦU VÀO'),p('b2','CLEANING + LOCKER SPEN',11.25,1,'LÀM SẠCH'),p('b3','SIDE KEY FPCB_BRK ASSY',12.28,1,'GẮN MẠCH'),p('b4','SIDE KEY ATTACH',10.69,1,'GẮN TAY'),p('b5','GẮN/ÉP + WATER LABEL + MARKING',10.11,1),p('b6','GẮN PHÍM + ROLLING',13.87,1,'ROLLING'),p('b7','RUBBER S PEN HOLDER + CHỐT SIM',11.65,1),p('b8','S PEN COVER + DINO SIM PIN',15.58,1),p('b9','SPONGE MESH MIC TOP + VT CAM',13.00,1),p('b10','AIR VENT ASSY / PRESS',12.30,1,'AIRVENT'),p('b11','UW CAM CONN + WIDE CAM BTM',13.53,1),p('b12','REMOVE LINER + LẮP TRAY SIM',11.03,1,'GẮN TAY'),p('b13','WPT TEST',16.22,0,'TEST TÍNH NĂNG',true),p('b14','TEST SPEN + THÁO TRAY SIM',8.43,1,'TEST TÍNH NĂNG'),p('b15','WLT TEST',15.98,0,'TEST TÍNH NĂNG',true),p('b16','VSWR TEST + CHECK VISION',15.26,0,'TEST TÍNH NĂNG',true),p('b17','OQC',15.22,1,'KIỂM TRA ĐẦU RA')
  ]}
},versions:[]};

function arrange(model){model.processes.forEach((s,i)=>{if(!s.x&&!s.y){const cols=7,row=Math.floor(i/cols),col=i%cols;s.x=35+(row%2?cols-1-col:col)*125;s.y=50+row*105;}})}
Object.values(seed.models).forEach(arrange);
let state=load(),currentKey=Object.keys(state.models)[0],selectedId=null,history=[];
const $=id=>document.getElementById(id); const clone=o=>JSON.parse(JSON.stringify(o));
function load(){try{return JSON.parse(localStorage.getItem(STORAGE))||clone(seed)}catch{return clone(seed)}}
function persist(){localStorage.setItem(STORAGE,JSON.stringify(state));$('saveState').innerHTML='<i></i>Đã lưu trên thiết bị'}
function snapshot(){history.push(clone(state));if(history.length>30)history.shift();}
function model(){return state.models[currentKey]}
function metrics(){const a=model().processes,neck=Math.max(0,...a.map(x=>+x.time||0)),sum=a.reduce((n,x)=>n+(+x.time||0),0),mp=a.reduce((n,x)=>n+(+x.mp||0),0);return{neck,sum,mp,uph:neck?3600/neck:0,lob:neck&&a.length?sum/(a.length*neck):0}}
function renderAll(){renderModels();renderList();renderCanvas();renderMetrics();renderInspector();renderVersions();persist()}
function renderModels(){$('modelSelect').innerHTML=Object.entries(state.models).map(([k,m])=>`<option value="${k}" ${k===currentKey?'selected':''}>${m.name} · ${m.version}</option>`).join('');$('layoutTitle').textContent=`Layout ${model().name} · ${model().version}`}
function renderMetrics(){const m=metrics();$('metricLob').textContent=(m.lob*100).toFixed(1)+'%';$('metricNeck').textContent=m.neck.toFixed(2);$('metricUph').textContent=m.uph.toFixed(0);$('metricCount').textContent=model().processes.length;$('metricMp').textContent=m.mp+' nhân lực'}
function renderList(){const q=$('searchInput').value.toLowerCase();$('processList').innerHTML=model().processes.filter(x=>x.name.toLowerCase().includes(q)).map((x,i)=>`<div class="process-item ${x.id===selectedId?'active':''}" data-id="${x.id}"><span class="num">${i+1}</span><span class="pname">${escapeHtml(x.name)}</span><span class="ptime">${(+x.time).toFixed(2)}s</span></div>`).join('');document.querySelectorAll('.process-item').forEach(el=>el.onclick=()=>select(el.dataset.id))}
function renderCanvas(){const box=$('layoutCanvas'),neck=metrics().neck;box.querySelectorAll('.station').forEach(x=>x.remove());model().processes.forEach((s,i)=>{const el=document.createElement('div');el.className=`station ${s.id===selectedId?'active':''} ${+s.time===neck?'neck':''} ${s.auto?'auto':''}`;el.dataset.id=s.id;el.style.left=s.x+'px';el.style.top=s.y+'px';el.innerHTML=`<div class="station-no">TRẠM ${String(i+1).padStart(2,'0')}</div><div class="station-name">${escapeHtml(s.name)}</div><div class="station-meta"><span>${(+s.time).toFixed(2)}s</span><span>${s.auto?'AUTO':s.mp+' MP'}</span></div>`;el.onpointerdown=startDrag;el.onclick=()=>select(s.id);box.appendChild(el)})}
function select(id){selectedId=id;renderList();renderCanvas();renderInspector();if(innerWidth<=1050)$('inspector').classList.add('open')}
function renderInspector(){const s=model().processes.find(x=>x.id===selectedId),form=$('editForm'),empty=$('emptyInspector');if(!s){form.classList.remove('visible');empty.style.display='block';$('stationBadge').textContent='TRẠM —';$('stationTitle').textContent='Chọn một trạm';return}empty.style.display='none';form.classList.add('visible');const i=model().processes.indexOf(s);$('stationBadge').textContent=`TRẠM ${String(i+1).padStart(2,'0')}`;$('stationTitle').textContent=s.name;$('nameInput').value=s.name;$('timeInput').value=s.time;$('mpInput').value=s.mp;$('categoryInput').value=s.category;$('autoInput').checked=s.auto}
function renderVersions(){const vs=state.versions.filter(v=>v.model===currentKey).slice().reverse();$('versionList').innerHTML=vs.length?vs.map(v=>`<div class="version-entry"><b>${escapeHtml(v.name)}</b><small>${escapeHtml(v.note||'Không có ghi chú')} · ${v.date}</small></div>`).join(''):'<small style="color:var(--muted)">Chưa có phiên bản đã lưu.</small>'}
function startDrag(e){const el=e.currentTarget,s=model().processes.find(x=>x.id===el.dataset.id),canvas=$('layoutCanvas'),r=canvas.getBoundingClientRect(),ox=e.clientX-r.left-s.x,oy=e.clientY-r.top-s.y,moved=false;select(s.id);snapshot();el.setPointerCapture(e.pointerId);el.onpointermove=ev=>{moved=true;s.x=Math.max(0,Math.min(canvas.clientWidth-118,ev.clientX-r.left-ox));s.y=Math.max(0,Math.min(canvas.clientHeight-76,ev.clientY-r.top-oy));el.style.left=s.x+'px';el.style.top=s.y+'px'};el.onpointerup=()=>{el.onpointermove=null;if(moved){persist();toast('Đã cập nhật vị trí trạm')}}}
function toast(msg){const t=$('toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1800)}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}

$('modelSelect').onchange=e=>{currentKey=e.target.value;selectedId=null;renderAll()};$('searchInput').oninput=renderList;
$('editForm').onsubmit=e=>{e.preventDefault();const s=model().processes.find(x=>x.id===selectedId);if(!s)return;snapshot();s.name=$('nameInput').value.trim()||s.name;s.time=Math.max(0,+$('timeInput').value||0);s.auto=$('autoInput').checked;s.mp=s.auto?0:Math.max(0,+$('mpInput').value||0);s.category=$('categoryInput').value;renderAll();toast('Đã áp dụng thay đổi')};
$('addBtn').onclick=()=>{snapshot();const id='p'+Date.now(),s=p(id,'Công đoạn mới',10,1);s.x=55;s.y=55;model().processes.push(s);selectedId=id;renderAll();select(id);toast('Đã thêm công đoạn')};
$('deleteBtn').onclick=()=>{if(!selectedId)return;snapshot();model().processes=model().processes.filter(x=>x.id!==selectedId);selectedId=null;renderAll();toast('Đã xóa công đoạn')};
$('undoBtn').onclick=()=>{if(!history.length)return toast('Không còn thao tác để hoàn tác');state=history.pop();if(!state.models[currentKey])currentKey=Object.keys(state.models)[0];selectedId=null;renderAll();toast('Đã hoàn tác')};
$('duplicateBtn').onclick=()=>{snapshot();const base=model(),key='model'+Date.now(),copy=clone(base);copy.name=base.name+' Copy';copy.version='Ver 0.1';copy.processes.forEach((x,i)=>x.id=key+'-'+i);state.models[key]=copy;currentKey=key;selectedId=null;renderAll();toast('Đã tạo bản sao layout')};
$('resetBtn').onclick=()=>{snapshot();state=clone(seed);currentKey='s948';selectedId=null;renderAll();toast('Đã khôi phục dữ liệu mẫu')};$('printBtn').onclick=()=>window.print();$('closeInspector').onclick=()=>{$('inspector').classList.remove('open');selectedId=null;renderInspector();renderCanvas();renderList()};
$('saveVersionBtn').onclick=()=>{$('versionName').value=model().version;$('versionNote').value='';$('versionDialog').showModal()};
$('versionForm').addEventListener('submit',e=>{if(e.submitter?.value==='cancel')return;e.preventDefault();snapshot();model().version=$('versionName').value.trim()||model().version;state.versions.push({model:currentKey,name:model().version,note:$('versionNote').value.trim(),date:new Date().toLocaleString('vi-VN'),snapshot:clone(model())});$('versionDialog').close();renderAll();toast('Đã lưu phiên bản')});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){$('undoBtn').click();e.preventDefault()}});
function registerTools(){const c=document.modelContext;if(!c?.registerTool)return;const safe=(name,time,mp)=>{if(!name||!Number.isFinite(+time)||+time<0||!Number.isFinite(+mp)||+mp<0)throw new Error('Dữ liệu công đoạn không hợp lệ');return{name:String(name),time:+time,mp:+mp}};try{c.registerTool({name:'add_lob_process',title:'Thêm công đoạn LOB',description:'Thêm một công đoạn vào model đang mở và cập nhật các chỉ số.',inputSchema:{type:'object',properties:{name:{type:'string'},time:{type:'number',minimum:0},mp:{type:'number',minimum:0}},required:['name','time','mp'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){const v=safe(input.name,input.time,input.mp),s=p('ai'+Date.now(),v.name,v.time,v.mp);s.x=55;s.y=55;snapshot();model().processes.push(s);selectedId=s.id;renderAll();return{added:s.id,model:model().name,metrics:metrics()}}});c.registerTool({name:'read_lob_summary',title:'Đọc chỉ số LOB',description:'Đọc chỉ số của model đang mở.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(){return{model:model().name,version:model().version,...metrics()}}})}catch(e){console.warn('WebMCP unavailable',e)}}
renderAll();registerTools();
